    r2 = _resp([("segunda", 0.0, 0.5)])
    d = t.costurar([r1, r2], [0.0, 60.0])
    eq([w["word"] for w in d["words"]], ["primeira", "segunda"],
       "ordem tem que ser a das fatias")


@caso
def t_costura_monotonica():
