                    _resp([("c", 0.0, 1.0), ("d", 1.0, 2.0)])], [0.0, 50.0])
    ts = [w["start"] for w in d["words"]]
    eq(ts, sorted(ts), f"timestamps saíram fora de ordem: {ts}")


@caso
def t_costura_segmentos_tambem():
